import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"界面模板","description":"","frontmatter":{},"headers":[],"relativePath":"modules/station/gui.md","filePath":"modules/station/gui.md","lastUpdated":0}`),a={name:`modules/station/gui.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="界面模板" tabindex="-1">界面模板 <a class="header-anchor" href="#界面模板" aria-label="Permalink to “界面模板”">​</a></h1><p>EmakiStation 有四份界面模板，放在 <code>plugins/EmakiStation/gui/</code> 下。</p><table tabindex="0"><thead><tr><th>模板</th><th>对应界面</th><th>工作站配置键</th></tr></thead><tbody><tr><td><code>station_catalog.yml</code></td><td>配方目录页（第一页）</td><td><code>layout</code></td></tr><tr><td><code>station_preview.yml</code></td><td>材料预览页（第二页）</td><td><code>preview_layout</code></td></tr><tr><td><code>station_queue.yml</code></td><td>合成队列页（第三页）</td><td><code>queue_layout</code></td></tr><tr><td><code>station_dismantle.yml</code></td><td>分解界面</td><td>分解站的 <code>layout</code></td></tr></tbody></table><p>前三页构成合成侧的三页结构：目录页左键直接提交、右键进入材料预览；预览页确认提交；队列页查看、取消、领取与购买队列位。分解界面独立，由 <code>/emakistation dismantle &lt;工作站&gt;</code> 进入。</p><h2 id="槽位必须显式写-type" tabindex="-1">槽位必须显式写 <code>type</code> <a class="header-anchor" href="#槽位必须显式写-type" aria-label="Permalink to “槽位必须显式写 type”">​</a></h2><p>EmakiStation 的槽位<strong>必须显式写 <code>type</code></strong>。CoreLib 的模板解析器只会为少数 Forge 专用键名自动推断类型，自定义键名不写 <code>type</code> 就只是纯装饰格。</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  recipe_list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;recipe_list&quot;</span></span></code></pre></div><h2 id="配方目录页可用类型" tabindex="-1">配方目录页可用类型 <a class="header-anchor" href="#配方目录页可用类型" aria-label="Permalink to “配方目录页可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>recipe_list</code></td><td>列出配方。<strong>必需</strong>，否则布局校验不通过。</td></tr><tr><td><code>queue_open</code></td><td>打开合成队列页。</td></tr><tr><td><code>batch_multiplier</code></td><td>循环切换倍率，左键递增、右键递减。</td></tr><tr><td><code>output_toggle</code></td><td>切换产物去向。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>翻页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>本页<strong>没有</strong> input 槽。玩家不放材料进界面，材料在提交时直接从背包与仓库合并扣除。</p><h2 id="材料预览页可用类型" tabindex="-1">材料预览页可用类型 <a class="header-anchor" href="#材料预览页可用类型" aria-label="Permalink to “材料预览页可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>material_list</code></td><td>列出所选配方的材料需求。<strong>必需</strong>。</td></tr><tr><td><code>recipe_display</code></td><td>显示当前预览的配方。</td></tr><tr><td><code>cost_display</code></td><td>显示货币成本与玩家余额。</td></tr><tr><td><code>max_craftable</code></td><td>显示按材料与余额最多能做几次，点击直接拉满。</td></tr><tr><td><code>batch_multiplier</code></td><td>循环切换倍率。</td></tr><tr><td><code>confirm</code></td><td>提交。</td></tr><tr><td><code>back</code></td><td>返回目录页，会停在原来那一页。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>材料列表翻页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>本页只读，不接受放入物品。</p><h3 id="材料数量的显示规则" tabindex="-1">材料数量的显示规则 <a class="header-anchor" href="#材料数量的显示规则" aria-label="Permalink to “材料数量的显示规则”">​</a></h3><table tabindex="0"><thead><tr><th>需求量</th><th>显示方式</th></tr></thead><tbody><tr><td>≤ 99</td><td>图标上带真实数字，客户端直接画出来。</td></tr><tr><td>≥ 100</td><td>图标数量固定为 1，不画数字，真实数量只出现在 lore 的 <code>%required_exact%</code>。</td></tr></tbody></table><p>因此 lore 里务必保留 <code>%required_exact%</code>，否则大额需求玩家将无从得知。</p><p>65~99 超过多数物品的自然堆叠上限，插件会临时抬高被渲染图标的 <code>max_stack_size</code> 组件。这个改动只作用于界面里的展示图标，永远不会交给玩家。</p><h2 id="合成队列页可用类型" tabindex="-1">合成队列页可用类型 <a class="header-anchor" href="#合成队列页可用类型" aria-label="Permalink to “合成队列页可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>queue_view</code></td><td>列出队列条目。<strong>必需</strong>。</td></tr><tr><td><code>capacity_display</code></td><td>显示已用 / 上限，以及上限的来源。</td></tr><tr><td><code>queue_purchase</code></td><td>购买额外队列位，左键买 1 个，Shift 买一整批。</td></tr><tr><td><code>claim_all</code></td><td>领取全部待领取产物。</td></tr><tr><td><code>back</code></td><td>返回目录页，会停在原来那一页。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>队列翻页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><p>本页只读，不接受放入物品。</p><h2 id="分解界面可用类型" tabindex="-1">分解界面可用类型 <a class="header-anchor" href="#分解界面可用类型" aria-label="Permalink to “分解界面可用类型”">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>作用</th></tr></thead><tbody><tr><td><code>dismantle_input</code></td><td>展示配方所需物品，即当前选中配方的输入图标。</td></tr><tr><td><code>dismantle_item_display</code></td><td>同 <code>dismantle_input</code>，别名。</td></tr><tr><td><code>dismantle_rolls_display</code></td><td>显示投掷次数范围（<code>%rolls_min%</code> / <code>%rolls_max%</code>）。</td></tr><tr><td><code>dismantle_output_list</code></td><td>分解产物列表，多格分页，含 <code>pool_entry</code> / <code>rolled_output</code> 虚拟物品。</td></tr><tr><td><code>dismantle_confirm</code></td><td>确认执行分解，或领取已投掷产物。</td></tr><tr><td><code>prev_page</code> / <code>next_page</code> / <code>page_info</code></td><td>产物列表翻页。</td></tr><tr><td><code>back</code></td><td>返回目录页。</td></tr><tr><td><code>close</code></td><td>关闭界面。</td></tr></tbody></table><h2 id="标题占位符" tabindex="-1">标题占位符 <a class="header-anchor" href="#标题占位符" aria-label="Permalink to “标题占位符”">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>可用页面</th></tr></thead><tbody><tr><td><code>%station_name%</code></td><td>配方目录页、合成队列页、分解界面。</td></tr><tr><td><code>%recipe_name%</code></td><td>材料预览页。</td></tr><tr><td><code>%used%</code> / <code>%max%</code></td><td>合成队列页。</td></tr></tbody></table><p>这些是模板内部占位符，由 EmakiStation 自己渲染，与 PlaceholderAPI 无关。</p><h2 id="virtual-items-与-texts" tabindex="-1"><code>virtual_items</code> 与 <code>texts</code> <a class="header-anchor" href="#virtual-items-与-texts" aria-label="Permalink to “virtual_items 与 texts”">​</a></h2><p>四份模板都有 <code>virtual_items</code> 段，用于定义列表项的图标形态，例如目录页的 <code>recipe_entry</code> / <code>recipe_locked</code>、预览页的 <code>material_satisfied</code> / <code>material_missing</code> / <code>confirm_blocked</code>、队列页的 <code>queue_entry</code> / <code>queue_pending</code> / <code>purchase_unavailable</code>、分解页的 <code>no_recipe</code> / <code>pool_entry</code> / <code>rolled_output</code> 等。</p><p>除分解界面外，三份合成模板还有 <code>texts</code> 段，用于配置行文本片段。分解界面没有 <code>texts</code> 段。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};